<?php /** @var array<string,mixed> $v */ /** @var ?string $payUrl */ /** @var int $payAmount */ use Vertex\Core\View; ?>
<div class="page-head"><div><p class="eyebrow"><?= e(config("renewals.types.{$v['type']}", $v['type'])) ?> · <?= e($v['reference']) ?></p><h1><?= e($v['identifier']) ?></h1></div><a class="btn btn-ghost" href="/my/services">&larr; Domains &amp; hosting</a></div>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><?= View::partial('rbadge', ['s' => $v['status']]) ?></div><div><span class="muted">Expires</span><br><strong><?= e(local_date($v['expires_on'])) ?></strong></div><div><span class="muted">Renewal period</span><br><?= (int) $v['period_months'] ?> months</div><div><span class="muted">Provider</span><br><?= e($v['provider']) ?></div></div>
    <p><?= e($v['stage']) ?></p><?php if ($v['client_notes']) : ?><p class="prewrap"><?= e($v['client_notes']) ?></p><?php endif; ?>
    <?php if ($v['last_renewed_at']) : ?><p class="muted">Last renewed <?= e(local_time($v['last_renewed_at'])) ?>.</p><?php endif; ?></div>
<?php if ($v['price']) : ?><div class="panel"><h2>Renewal price</h2><?php if ($v['price']['waived']) : ?><p>No charge for this renewal.</p><?php else : ?><dl class="detail-list"><dt>Price</dt><dd><?= e(money($v['price']['net_minor'])) ?></dd><dt>Tax</dt><dd><?= e(money($v['price']['tax_minor'])) ?></dd><dt>Total</dt><dd><strong><?= e(money($v['price']['total_minor'])) ?></strong> for <?= (int) $v['price']['period_months'] ?> months<?= $v['adjustment_minor'] > 0 ? ' <span class="muted">(includes ' . e(money($v['adjustment_minor'])) . ' because the provider raised its price)</span>' : '' ?></dd></dl><?php endif; ?>
    <?php if ($v['invoice_ref']) : ?><dl class="detail-list"><dt>Invoice</dt><dd><?= e($v['invoice_ref']) ?><?= $v['quotation_ref'] ? ' · quotation ' . e($v['quotation_ref']) : '' ?></dd><dt>Paid so far</dt><dd><?= e(money($v['paid_minor'])) ?> of <?= e(money($v['invoice_amount_minor'])) ?></dd></dl>
        <?php if ($v['status'] === 'awaiting_payment' || $v['status'] === 'invoice_issued') : ?><?php if ($payUrl !== null) : ?><p><a class="btn btn-primary" href="<?= e($payUrl) ?>">Pay <?= e(money($payAmount)) ?> online</a></p><?php else : ?><p class="muted">Please pay using the instructions on your invoice and quote the invoice number; we will record your payment and update this page. If we send you an online payment request it will appear here.</p><?php endif; ?><?php endif; ?><?php endif; ?></div><?php endif; ?>
<?php if (in_array($v['status'], ['approved_for_renewal', 'invoice_issued', 'awaiting_payment', 'payment_received', 'renewal_in_progress', 'renewed'], true)) : ?><div class="panel"><h2>Progress</h2><ol class="steps"><?php foreach ($v['steps'] as $st) : ?><li class="step step-<?= e($st['state']) ?>"><?= e($st['label']) ?></li><?php endforeach; ?></ol></div><?php endif; ?>
